/**
 * Domino course layout + Rapier world helpers (three-free so it can be tested headless).
 * The course is generated by a "turtle" that walks a dense path and drops a domino every SP of arc length.
 */
import type { RapierContext, RapierRigidBody } from '@react-three/rapier'

type R = RapierContext['rapier']
type W = RapierContext['world']

export const DH = 1.0 // height
export const DW = 0.5 // width
export const DT = 0.16 // thickness
export const SP = 0.58 // centre-to-centre spacing along the path
export const RISE = 0.19 // stair rise
export const GRAVITY = -30

export const SEG = { spiral: 0, s: 1, stairs: 2, uturn: 3, branchA: 4, branchB: 5, lead: 6, field: 7 } as const
export type Seg = (typeof SEG)[keyof typeof SEG]

export type Dom = {
  x: number
  y: number // base height
  z: number
  yaw: number // forward = (sin yaw, 0, cos yaw)
  seg: Seg
  heart: boolean
  order: number // progress order (field rows share their row number)
}
export type Block = { x: number; y: number; z: number; hx: number; hy: number; hz: number; yaw: number }

export type Course = {
  doms: Dom[]
  blocks: Block[]
  field: { x: number; z: number; yaw: number; len: number; half: number; start: number }
  bounds: { minX: number; maxX: number; minZ: number; maxZ: number }
}

export function buildCourse(): Course {
  const doms: Dom[] = []
  const blocks: Block[] = []
  let order = 0
  const put = (x: number, y: number, z: number, yaw: number, seg: Seg, heart = false, ord = order++) =>
    doms.push({ x, y, z, yaw, seg, heart, order: ord })

  /* --- spiral, starting at its heart and winding outwards (no crossing needed) */
  const CX = -10.4
  const CZ = -0.6
  const r0 = 1.45
  const pitch = 1.42
  const turns = 1.72
  const pts: [number, number][] = []
  const phiEnd = turns * Math.PI * 2
  for (let p = 0; p <= phiEnd + 1e-6; p += 0.002) {
    const r = r0 + (pitch * p) / (Math.PI * 2)
    pts.push([Math.cos(-p) * r, Math.sin(-p) * r])
  }
  // rotate so the exit tangent points +x, exit point below the centre (+z)
  const n = pts.length
  const ex = pts[n - 1][0] - pts[n - 2][0]
  const ez = pts[n - 1][1] - pts[n - 2][1]
  const rot = Math.atan2(ez, ex) // current exit direction angle (x-z plane)
  const c = Math.cos(-rot)
  const s = Math.sin(-rot)
  let flip = 1
  {
    const [lx, lz] = pts[n - 1]
    const zz = lx * s + lz * c
    if (zz < 0) flip = -1 // mirror in z so the exit sits on the +z side
  }
  const sp = pts.map(([x, z]) => [CX + (x * c - z * s), CZ + flip * (x * s + z * c)] as [number, number])
  let acc = SP // drop the first domino at the very start
  for (let i = 1; i < sp.length; i++) {
    const dx = sp[i][0] - sp[i - 1][0]
    const dz = sp[i][1] - sp[i - 1][1]
    acc += Math.hypot(dx, dz)
    if (acc >= SP) {
      acc -= SP
      put(sp[i][0], 0, sp[i][1], Math.atan2(dx, dz), SEG.spiral)
    }
  }

  /* --- turtle for the rest */
  const T = { x: sp[sp.length - 1][0], z: sp[sp.length - 1][1], h: Math.PI / 2, acc }
  const DS = 0.004
  const walk = (len: number, curv: number, seg: Seg, y = () => 0) => {
    const steps = Math.max(1, Math.round(len / DS))
    const ds = len / steps
    for (let k = 0; k < steps; k++) {
      T.h += curv * ds * 0.5
      T.x += Math.sin(T.h) * ds
      T.z += Math.cos(T.h) * ds
      T.h += curv * ds * 0.5
      T.acc += ds
      if (T.acc >= SP) {
        T.acc -= SP
        put(T.x, y(), T.z, T.h, seg)
      }
    }
  }
  const arc = (r: number, deg: number, seg: Seg) => walk((Math.abs(deg) * Math.PI * r) / 180, (Math.sign(deg) * 1) / r, seg)
  const straight = (len: number, seg: Seg) => walk(len, 0, seg)

  /* --- S-curve (heading +x) */
  straight(0.6, SEG.s)
  arc(2.7, -62, SEG.s)
  arc(2.7, 124, SEG.s)
  arc(2.7, -62, SEG.s)
  straight(1.2, SEG.s)

  /* --- staircase up, landing, down — one domino per tread */
  const fwd = () => [Math.sin(T.h), Math.cos(T.h)]
  const levels = [1, 2, 3, 4, 5, 5, 5, 4, 3, 2, 1]
  for (const lv of levels) {
    const [fx, fz] = fwd()
    T.x += fx * (SP - T.acc)
    T.z += fz * (SP - T.acc)
    T.acc = 0
    const yb = lv * RISE
    put(T.x, yb, T.z, T.h, SEG.stairs)
    blocks.push({ x: T.x, y: yb / 2, z: T.z, hx: 0.62, hy: yb / 2, hz: SP / 2, yaw: T.h })
  }
  straight(1.6, SEG.stairs)

  /* --- U-turn towards +z */
  arc(4.4, -180, SEG.uturn)
  straight(0.9, SEG.uturn)

  /* --- split into two branches that rejoin (same length → they arrive together) */
  {
    const L = 8.2
    const A = 1.9
    const off0 = 0.27
    const [fx, fz] = fwd()
    const lx = fz
    const lz = -fx
    const ox = T.x - fx * T.acc // path origin = last domino
    const oz = T.z - fz * T.acc
    for (const side of [1, -1]) {
      let a = SP * 0.94
      let px = ox + fx * 0 + lx * side * off0
      let pz = oz + fz * 0 + lz * side * off0
      for (let u = 0.002; u <= L + 1e-6; u += 0.002) {
        const d = off0 + A * Math.sin((Math.PI * u) / L) ** 2
        const qx = ox + fx * u + lx * side * d
        const qz = oz + fz * u + lz * side * d
        const dd = Math.hypot(qx - px, qz - pz)
        a += dd
        if (a >= SP && u < L - 0.25) {
          a -= SP
          put(qx, 0, qz, Math.atan2(qx - px, qz - pz), side > 0 ? SEG.branchA : SEG.branchB, false, -1)
        }
        px = qx
        pz = qz
      }
    }
    // progress order: interleave the two branches by distance along the axis
    const br = doms.filter((d) => d.order === -1)
    br.sort((p, q) => (p.x - ox) * fx + (p.z - oz) * fz - ((q.x - ox) * fx + (q.z - oz) * fz))
    br.forEach((d) => (d.order = order + Math.floor(((d.x - ox) * fx + (d.z - oz) * fz) / SP)))
    order += Math.ceil(L / SP) + 1
    T.x = ox + fx * (L + SP * 0.94)
    T.z = oz + fz * (L + SP * 0.94)
    T.acc = 0
    put(T.x, 0, T.z, T.h, SEG.lead)
  }
  straight(1.8, SEG.lead)

  /* --- the field: a staggered fan that widens one domino per row, then a block; the heart is in the tops */
  const ROWS_T = 17
  const ROWS = 24
  const P = 0.6
  const [fx, fz] = fwd()
  const lx = fz
  const lz = -fx
  const fx0 = T.x + fx * (SP - T.acc)
  const fz0 = T.z + fz * (SP - T.acc)
  const half = ((ROWS_T - 1) / 2) * P
  const len = (ROWS - 1) * SP
  const fieldStart = doms.length
  // heart = two round lobes + a V down to the tip (tip at the entry, lobes at the far end)
  const lobeR = 2.05
  const lobeC = 1.95
  const lobeV = len - lobeR - 0.45
  const tipV = 1.3
  const vK = (lobeC + lobeR * 0.93) / (lobeV - tipV)
  const inHeart = (u: number, v: number) => {
    const au = Math.abs(u)
    if ((au - lobeC) ** 2 + (v - lobeV) ** 2 <= lobeR * lobeR) return true
    return v >= tipV && v <= lobeV && au <= (v - tipV) * vK
  }
  for (let k = 0; k < ROWS; k++) {
    for (let j = 0; j <= k; j++) {
      const lat = (j - k / 2) * P
      if (Math.abs(lat) > half + 1e-6) continue
      const fwdD = k * SP
      put(fx0 + fx * fwdD + lx * lat, 0, fz0 + fz * fwdD + lz * lat, T.h, SEG.field, inHeart(lat, fwdD), order + k)
    }
  }
  order += ROWS

  let minX = Infinity
  let maxX = -Infinity
  let minZ = Infinity
  let maxZ = -Infinity
  for (const d of doms) {
    minX = Math.min(minX, d.x)
    maxX = Math.max(maxX, d.x)
    minZ = Math.min(minZ, d.z)
    maxZ = Math.max(maxZ, d.z)
  }
  return {
    doms,
    blocks,
    field: { x: fx0 + (fx * len) / 2, z: fz0 + (fz * len) / 2, yaw: T.h, len, half, start: fieldStart },
    bounds: { minX, maxX, minZ, maxZ },
  }
}

/* ------------------------------------------------------------------ world */

export function quatYaw(yaw: number) {
  return { x: 0, y: Math.sin(yaw / 2), z: 0, w: Math.cos(yaw / 2) }
}

export function createBodies(RAPIER: R, world: W, course: Course): { list: RapierRigidBody[]; statics: RapierRigidBody[] } {
  const statics: RapierRigidBody[] = []
  const ground = world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(0, -0.5, 0))
  world.createCollider(RAPIER.ColliderDesc.cuboid(80, 0.5, 80).setFriction(0.8), ground)
  statics.push(ground)
  for (const b of course.blocks) {
    const rb = world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(b.x, b.y, b.z).setRotation(quatYaw(b.yaw)))
    world.createCollider(RAPIER.ColliderDesc.cuboid(b.hx, b.hy, b.hz).setFriction(0.8), rb)
    statics.push(rb)
  }
  const list: RapierRigidBody[] = []
  for (const d of course.doms) {
    const rb = world.createRigidBody(
      RAPIER.RigidBodyDesc.dynamic()
        .setTranslation(d.x, d.y + DH / 2, d.z)
        .setRotation(quatYaw(d.yaw))
        .setCanSleep(true)
        .setLinearDamping(0.02)
        .setAngularDamping(0.08),
    )
    world.createCollider(RAPIER.ColliderDesc.cuboid(DW / 2, DH / 2, DT / 2).setFriction(0.55).setRestitution(0).setDensity(1), rb)
    rb.sleep()
    list.push(rb)
  }
  return { list, statics }
}

export function resetBody(rb: RapierRigidBody, d: Dom) {
  rb.setTranslation({ x: d.x, y: d.y + DH / 2, z: d.z }, false)
  rb.setRotation(quatYaw(d.yaw), false)
  rb.setLinvel({ x: 0, y: 0, z: 0 }, false)
  rb.setAngvel({ x: 0, y: 0, z: 0 }, false)
  rb.sleep()
}

/** tip a domino forward */
export function push(rb: RapierRigidBody, d: Dom, w = 3.2) {
  const fx = Math.sin(d.yaw)
  const fz = Math.cos(d.yaw)
  // rigid rotation about the front-bottom edge
  rb.setAngvel({ x: fz * w, y: 0, z: -fx * w }, true)
  rb.setLinvel({ x: fx * w * (DH / 2), y: w * (DT / 2), z: fz * w * (DH / 2) }, true)
}

/** cosine of the tilt from vertical (1 = standing) */
export function upY(rb: RapierRigidBody) {
  const q = rb.rotation()
  return 1 - 2 * (q.x * q.x + q.z * q.z)
}
